import{_ as a,o as _,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2024Q2 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2024Q2 Ceph社区季度进展报告","date":"2024-06-01T00:00:00.000Z","updated":"2024-06-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/2024Q2_Ceph社区季度总结.md","filePath":"posts/2024/2024Q2_Ceph社区季度总结.md","lastUpdated":1780460162000}'),t={name:"posts/2024/2024Q2_Ceph社区季度总结.md"};function o(s,e,h,l,n,p){return _(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ceph-社区-2024q2-季度进展报告" tabindex="-1">Ceph 社区 2024Q2 季度进展报告 <a class="header-anchor" href="#ceph-社区-2024q2-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2024Q2 季度进展报告&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>2024Q2 季度以 <strong>Ceph Days NYC 2024</strong> 为核心活动，围绕以下技术方向展开了密集讨论：</p><p><strong>性能优化</strong>是本季度最突出的主题，涵盖全闪存 RBD 调优、NVMe 存储方案、Discard 性能改进等多个维度。详见 <a href="/VideoSummary/posts/2024/Designing_and_Tuning_for_All-Flash_Ceph_RBD_Storage_Ceph_Days_NYC_2024.html">Designing_and_Tuning_for_All-Flash_Ceph_RBD_Storage_Ceph_Days_NYC_2024</a>) 和 <a href="/VideoSummary/posts/2024/Ceph_-_A_Journey_to_1_TiB_s_Ceph_Days_NYC_2024.html">Ceph_-_A_Journey_to_1TiB_s_Ceph_Days_NYC_2024</a>)。</p><p><strong>新存储协议接入</strong>方面，NVMe-oF 作为替代 iSCSI 的下一代块存储接入方案受到重点关注，详见 <a href="/VideoSummary/posts/2024/NVMe-Over-Fabrics_Support_for_Ceph_Ceph_Days_NYC_2024.html">NVMe-Over-Fabrics_Support_for_Ceph_Ceph_Days_NYC_2024</a>)。</p><p><strong>社区治理与用户反馈机制</strong>方面，SEF 用户委员会正式启动，通过结构化调查收集用户需求，详见 <a href="/VideoSummary/posts/2024/Community_Initiatives_and_Improving_Ceph_through_User_Feedback_Ceph_Days_NYC_2024.html">Community_Initiatives_and_Improving_Ceph_through_User_Feedback_Ceph_Days_NYC_2024</a>)。</p><p><strong>数据安全与存储加固</strong>、灾难恢复**、<strong>多租户文件系统</strong>也是本季度反复出现的议题。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="_2-1-squid-版本特性预览" tabindex="-1">2.1 Squid 版本特性预览 <a class="header-anchor" href="#_2-1-squid-版本特性预览" aria-label="Permalink to &quot;2.1 Squid 版本特性预览&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Diving_Deep_with_Squid_Ceph_Days_NYC_2024.html">Diving_Deep_with_Squid_Ceph_Days_NYC_2024</a>) 系统介绍了即将发布的 Squid 版本核心改进：</p><ul><li><strong>Elastic Shared Blob</strong>：降低快照工作负载的延迟和 CPU 开销</li><li><strong>BlueStore 引入 RocksDB LZ4 压缩</strong>：提升性能并减少空间占用</li><li><strong>CRUSH 算法改进</strong>：支持更灵活的 EC（Erasure Coding）配置</li><li><strong>Balancer 在线平衡能力增强</strong></li><li><strong>Manager OP Tracker</strong>：简化生产环境调试</li><li><strong>Crimson 读取性能显著提升</strong>，稳定性增强</li><li><strong>Sea Store多核扩展优化</strong></li></ul><h3 id="_2-2-nvme-of-gateway" tabindex="-1">2.2 NVMe-oF Gateway <a class="header-anchor" href="#_2-2-nvme-of-gateway" aria-label="Permalink to &quot;2.2 NVMe-oF Gateway&quot;">​</a></h3><p><a href="./NVMe-Over-Fabrics_Support_for_Ceph_Days_NYC_2024.html">NVMe-Over-Fabrics_Support_for_Ceph_Ceph_Days_NYC_2024</a> 展示了基于 SPDK 的 NVMe over TCP Gateway 方案：</p><ul><li>相比 iSCSI，在吞吐量、IOPS、延迟三项指标上均有显著优势</li><li>支持多路径和负载均衡，Gateway 配置存储于 omap 中</li><li>支持 TLS PSK 加密通信，VMware vSphere VASA 集成已在推进中</li></ul><h3 id="_2-3-全闪存-rbd-性能调优实践" tabindex="-1">2.3 全闪存 RBD 性能调优实践 <a class="header-anchor" href="#_2-3-全闪存-rbd-性能调优实践" aria-label="Permalink to &quot;2.3 全闪存 RBD 性能调优实践&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Designing_and_Tuning_for_All-Flash_Ceph_RBD_Storage_Ceph_Days_NYC_2024.html">Designing_and_Tuning_for_All-Flash_Ceph_RBD_Storage_Ceph_Days_NYC_2024</a>) 来自 Bloomberg，分享了大规模全闪存集群的调优经验：</p><ul><li>NUMA 优化显著降低上下文切换</li><li>优化 NIC 驱动 RSS 处理，减少 CPU 热点</li><li>CRC32 计算优化，建议 Ceph 默认采用更高效实现</li><li>基于 L3 网络架构实现无客户影响的滚动升级</li></ul><h3 id="_2-4-突破-1-tib-s-性能目标" tabindex="-1">2.4 突破 1 TiB/s 性能目标 <a class="header-anchor" href="#_2-4-突破-1-tib-s-性能目标" aria-label="Permalink to &quot;2.4 突破 1 TiB/s 性能目标&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_-_A_Journey_to_1_TiB_s_Ceph_Days_NYC_2024.html">Ceph_-_A_Journey_to_1_TiB_s_Ceph_Days_NYC_2024</a>) 记录了在 320 个 OSD 配置下实现线性扩展，3x 复制模式下达到 1 TiB/s 读取性能的完整过程，关键优化点包括 NUMA 调优、BIOS C-States 禁用、IMU 禁用。</p><h3 id="_2-5-rbd-快照镜像灾难恢复增强" tabindex="-1">2.5 RBD 快照镜像灾难恢复增强 <a class="header-anchor" href="#_2-5-rbd-快照镜像灾难恢复增强" aria-label="Permalink to &quot;2.5 RBD 快照镜像灾难恢复增强&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Making_RBD_Snapshot-based_Mirroring_Robust_for_Disaster_Recovery_Ceph_Days_NYC_2024.html">Making_RBD_Snapshot-based_Mirroring_Robust_for_Disaster_Recovery_Ceph_Days_NYC_2024</a>) 介绍了 IBM 对 RBD 快照基础镜像的多项修复：</p><ul><li>修复快照对象映射不正确导致的数据损坏问题</li><li>解决镜像快照调度器被 krbd 客户端错误阻止的问题</li><li>改进高延迟环境下镜像守护进程行为</li><li>结合 ramen 操作符实现 Kubernetes 跨区域灾难恢复，RTO 目标分钟级</li></ul><h3 id="_2-6-discard-性能改进探索" tabindex="-1">2.6 Discard 性能改进探索 <a class="header-anchor" href="#_2-6-discard-性能改进探索" aria-label="Permalink to &quot;2.6 Discard 性能改进探索&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Attempting_to_Improve_Discard_Performance_Ceph_Days_NYC_2024.html">Attempting_to_Improve_Discard_Performance_Ceph_Days_NYC_2024</a>) 深入分析了 BlueStore 在 NVMe 驱动满载场景下的 Discard 性能瓶颈，探索了异步 Discard、线程池扩展、AVL 分配器与混合分配器对比等方向。</p><h3 id="_2-7-数据放置与-upmap-优化" tabindex="-1">2.7 数据放置与 Upmap 优化 <a class="header-anchor" href="#_2-7-数据放置与-upmap-优化" aria-label="Permalink to &quot;2.7 数据放置与 Upmap 优化&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_Data_Placement_with_Upmap_Introducing_Chorus_Ceph_Days_NYC_2024.html">Ceph_Data_Placement_with_Upmap_Introducing_Chorus_Ceph_Days_NYC_2024</a>) 强调了 Upmap 工具作为数据分布最终校正步骤的重要性，建议将其设为默认配置，并介绍了用于 S3 集群数据迁移的开源工具 Chorus。</p><h3 id="_2-8-多租户-cephfs-云环境设计" tabindex="-1">2.8 多租户 CephFS 云环境设计 <a class="header-anchor" href="#_2-8-多租户-cephfs-云环境设计" aria-label="Permalink to &quot;2.8 多租户 CephFS 云环境设计&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Designing_a_Multitenancy_File_System_for_Cloud_Environment_Ceph_Days_NYC_2024.html">Designing_aMultitenancy_File_System_for_Cloud_Environment_Ceph_Days_NYC_2024</a>) 展示了基于 RADOS 命名空间实现租户数据隔离、DM-Crypt 静态加密、Proxmox 虚拟化网关的完整多租户 CephFS 方案，服务于媒体娱乐行业远程编辑场景。</p><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><ul><li><strong>Squid 版本 RC 即将发布</strong>：<a href="/VideoSummary/posts/2024/Diving_Deep_with_Squid_Ceph_Days_NYC_2024.html">Diving_Deep_with_Squid_Ceph_Days_NYC_2024</a>) 确认 RC 版本将在数周内发布，邀请社区测试</li><li><strong>Ceph 管理存储量突破 1 exabyte</strong>，预计年内达到 1.5 exabytes</li><li><strong>Reef 版本成为最广泛部署的版本</strong></li><li><strong>Upmap 建议设为默认配置</strong>，由 CERN 代表在 Ceph Days NYC 提出</li><li><strong>NVMe-oF Gateway 进入生产就绪阶段</strong>，VMware 集成持续推进</li><li><strong>SEF 用户委员会正式成立</strong>，建了结构化的用户反馈到行动项转化机制</li></ul><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><h3 id="_4-1-ceph-days-nyc-2024" tabindex="-1">4.1 Ceph Days NYC 2024 <a class="header-anchor" href="#_4-1-ceph-days-nyc-2024" aria-label="Permalink to &quot;4.1 Ceph Days NYC 2024&quot;">​</a></h3><p>本季度最重要的社区活动，汇聚了来自 Bloomberg、DigitalOcean、IBM、CERN、45 Drives 等机构的工程师，覆盖性能、安全、运维、新协议等多个技术方向，共产出 14 篇技术分享。</p><h3 id="_4-2-用户委员会与调查" tabindex="-1">4.2 用户委员会与调查 <a class="header-anchor" href="#_4-2-用户委员会与调查" aria-label="Permalink to &quot;4.2 用户委员会与调查&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Community_Initiatives_and_Improving_Ceph_through_User_Feedback_Ceph_Days_NYC_2024.html">Community_Initiatives_and_Improving_Ceph_through_User_Feedback_Ceph_Days_NYC_2024</a>) 和 <a href="/VideoSummary/posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-05-23.html">Ceph_User_+_Dev_Monthly_Meeting_2024-05-23</a>) 记录了用户委员会的运作情况：</p><ul><li>收到 27 份调查回复，覆盖 Orchestration 和 Performance 两大支柱</li><li>主要工作负载：备份归档、持久容器/Kubernetes</li><li>用户对 cephadm 总体满意，但指出命令复杂、日志调试困难等问题</li><li>mclock 调度器文档不足是高频反馈</li><li>约 50% 用户未启用 Telemetry，主因是功能认知不足和隐私顾虑</li></ul><h3 id="_4-3-开发者月度会议" tabindex="-1">4.3 开发者月度会议 <a class="header-anchor" href="#_4-3-开发者月度会议" aria-label="Permalink to &quot;4.3 开发者月度会议&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_Developer_Monthly_2024-04-17.html">Ceph_Developer_Monthly_2024-04-17</a>) 聚焦于用户调查结果分析，确定了性能调优和可用性改进的优先方向，并计划在 Ceph Day New York 上公开展示调查结果。</p><h3 id="_4-4-大规模运营实践分享" tabindex="-1">4.4 大规模运营实践分享 <a class="header-anchor" href="#_4-4-大规模运营实践分享" aria-label="Permalink to &quot;4.4 大规模运营实践分享&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/How_we_Operate_Ceph_at_Scale_Ceph_Days_NYC_2024.html">How_we_Operate_Ceph_at_Scale_Ceph_Days_NYC_2024</a>) 来自 DigitalOcean，披露了其 58 个集群、200PB+ 原始存储、28,000 个 OSD 的运营规模，分享了基于 Chef + Ansible + AWX 的自动化运维体系和 Marigraph 延迟监控工具。</p><h3 id="_4-5-安全加固专题" tabindex="-1">4.5 安全加固专题 <a class="header-anchor" href="#_4-5-安全加固专题" aria-label="Permalink to &quot;4.5 安全加固专题&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Data_Security_and_Storage_Hardening_in_Rook_and_Ceph_Ceph_Days_NYC_2024.html">Data_Security_and_Storage_Hardening_in_Rook_and_Ceph_Days_NYC_2024</a>) 由 IBM 主导，讨论了基于威胁模型的安全策略、DM-crypt 静态加密、Messenger v2.1 传输加密，以及自动化依赖更新和漏洞扫描实践。</p><h3 id="_4-6-中小型数据中心应用推广" tabindex="-1">4.6 中小型数据中心应用推广 <a class="header-anchor" href="#_4-6-中小型数据中心应用推广" aria-label="Permalink to &quot;4.6 中小型数据中心应用推广&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Practical_Business_Ceph_Examples_Ceph_Days_NYC_2024.html">Practical_Business_Ceph_Examples_Ceph_Days_NYC_2024</a>) 通过多个实际案例（Proxmox + Ceph、VMware + Ceph、Kubernetes CSI、RGW + HAProxy）展示了 Ceph 在中小型数据中心的适用性，有助于扩大社区用户基础。</p><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度讨论内容，预计 2024Q3 将重点推进以下方向：</p><ol><li><p><strong>Squid 正式发布</strong>：RC 测试完成后发布 GA 版本，Elastic Shared Blob、BlueStore LZ4 压缩等特性进入生产可用状态</p></li><li><p><strong>Crimson/Sea Store 成熟度提升</strong>：本季度多次提及 Crimson 性能改进，预计持续推进多核扩展和稳定性工作</p></li><li><p><strong>NVMe-oF Gateway 功能完善</strong>：完成与 RBD 接口的完整映射，推进 inband 认证支持</p></li><li><p><strong>RBD 镜像功能扩展</strong>：镜像组（Mirror Groups）和 RBD 克隆镜像支持已列入后续开发计划</p></li><li><p><strong>用户委员会行动项落地</strong>：基于 Q2 调查结果，预计在 mclock 文档、cephadm 日志改进、Telemetry 推广等方面有具体产出</p></li><li><p><strong>Discard 性能持续优化</strong>：分配器对比测试结果将指导后续 BlueStore 配置建议</p></li><li><p><strong>SEFON 会议（CERN）</strong>：计划于 2023 年 12 月在 CERN 举办，Q3 将进入筹备阶段</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2024/Attempting_to_Improve_Discard_Performance_Ceph_Days_NYC_2024.html">Attempting to Improve Discard Performance | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_-_A_Journey_to_1_TiB_s_Ceph_Days_NYC_2024.html">Ceph: A Journey to 1 TiB/s | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_Data_Placement_with_Upmap_Introducing_Chorus_Ceph_Days_NYC_2024.html">Ceph Data Placement with Upmap / Introducing Chorus | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_Developer_Monthly_2024-04-17.html">Ceph Developer Monthly 2024-04-17</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-05-23.html">Ceph User + Dev Monthly Meeting 2024-05-23</a>)</li><li><a href="/VideoSummary/posts/2024/Community_Initiatives_and_Improving_Ceph_through_User_Feedback_Ceph_Days_NYC_2024.html">Community Initiatives and Improving Ceph through User Feedback | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Data_Security_and_Storage_Hardening_in_Rook_and_Ceph_Ceph_Days_NYC_2024.html">Data Security and Storage Hardening in Rook and Ceph | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Designing_a_Multitenancy_File_System_for_Cloud_Environment_Ceph_Days_NYC_2024.html">Designing a Multitenancy File System for Cloud Environment | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Designing_and_Tuning_for_All-Flash_Ceph_RBD_Storage_Ceph_Days_NYC_2024.html">Designing and Tuning for All-Flash Ceph RBD Storage | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Diving_Deep_with_Squid_Ceph_Days_NYC_2024.html">Diving Deep with Squid | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/How_we_Operate_Ceph_at_Scale_Ceph_Days_NYC_2024.html">How we Operate Ceph at Scale | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Making_RBD_Snapshot-based_Mirroring_Robust_for_Disaster_Recovery_Ceph_Days_NYC_2024.html">Making RBD Snapshot-based Mirroring Robust for Disaster Recovery | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/NVMe-Over-Fabrics_Support_for_Ceph_Ceph_Days_NYC_2024.html">NVMe-Over-Fabrics Support for Ceph | Ceph Days NYC 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Practical_Business_Ceph_Examples_Ceph_Days_NYC_2024.html">Practical Business Ceph Examples | Ceph Days NYC 2024</a>)</li></ul>',55)])])}const d=a(t,[["render",o]]);export{m as __pageData,d as default};
